// 時間複雜度: O(n)，空間複雜度: O(1)
function rob(nums) {
    let prev2 = 0, prev1 = 0;
    for (const x of nums) {
        const cur = Math.max(prev1, prev2 + x);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

