#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    /**
     * 方法一：動態規劃
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    int rob(vector<int>& nums) {
        if (nums.empty()) return 0;
        if (nums.size() == 1) return nums[0];

        int n = nums.size();
        vector<int> dp(n + 1, 0);
        dp[1] = nums[0];

        for (int i = 2; i <= n; i++) {
            dp[i] = max(dp[i-1], dp[i-2] + nums[i-1]);
        }

        return dp[n];
    }

    /**
     * 方法二：空間優化（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int rob_optimized(vector<int>& nums) {
        if (nums.empty()) return 0;
        if (nums.size() == 1) return nums[0];

        int prev2 = 0, prev1 = nums[0];

        for (int i = 1; i < nums.size(); i++) {
            int current = max(prev1, prev2 + nums[i]);
            prev2 = prev1;
            prev1 = current;
        }

        return prev1;
    }

    /**
     * 最簡潔版本
     */
    int rob_clean(vector<int>& nums) {
        int prev = 0, curr = 0;

        for (int num : nums) {
            int temp = curr;
            curr = max(curr, prev + num);
            prev = temp;
        }

        return curr;
    }
};

