class Solution {
    /**
     * 方法一：動態規劃
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    public int rob(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        if (nums.length == 1) return nums[0];

        int n = nums.length;
        int[] dp = new int[n + 1];
        dp[1] = nums[0];

        for (int i = 2; i <= n; i++) {
            dp[i] = Math.max(dp[i-1], dp[i-2] + nums[i-1]);
        }

        return dp[n];
    }

    /**
     * 方法二：空間優化（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public int rob_optimized(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        if (nums.length == 1) return nums[0];

        int prev2 = 0, prev1 = nums[0];

        for (int i = 1; i < nums.length; i++) {
            int current = Math.max(prev1, prev2 + nums[i]);
            prev2 = prev1;
            prev1 = current;
        }

        return prev1;
    }

    /**
     * 最簡潔版本
     */
    public int rob_clean(int[] nums) {
        int prev = 0, curr = 0;

        for (int num : nums) {
            int temp = curr;
            curr = Math.max(curr, prev + num);
            prev = temp;
        }

        return curr;
    }
}

