// DP 滾動變數：偷第 i 間（prev2 + nums[i]）或不偷（prev1）
// 時間複雜度: O(n)，空間複雜度: O(1)
int rob(int* nums, int numsSize) {
    int prev2 = 0, prev1 = 0;
    for (int i = 0; i < numsSize; i++) {
        int take = prev2 + nums[i];
        int cur = take > prev1 ? take : prev1;
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}
